// resolveURL joins the client base path with the builder path and appends the
// accumulated query parameters.
func (b *Builder) resolveURL(client *blogger.Client) (string, error) {
	path := b.basePath
	if !strings.HasPrefix(path, "http://") && !strings.HasPrefix(path, "https://") {
		path = strings.TrimRight(client.BasePath, "/") + "/" + strings.TrimLeft(path, "/")
	}

	parsed, err := url.Parse(path)
	if err != nil {
		return "", err
	}

	query := parsed.Query()
	for key, value := range b.queryParams {
		query.Set(key, value)
	}
	parsed.RawQuery = query.Encode()

	return parsed.String(), nil
}

// compile-time assertion that the builder sends plain requests through the
// generated client.
var _ interface {
	Do(*http.Request) (*http.Response, error)
} = (*blogger.Client)(nil)

