package builder

// Xgafv selects the API version of the Google API surface being called.
const (
	Xgafv = "xgafv"
)

// Authentication and standard Google API System Parameters. Any of these can be
// passed to Builder.Param.
const (
	AccessToken = "access_token"
	Timestamp   = "timestamp"
	OauthToken  = "oauth_token"
)

// Output-shaping standard parameters.
const (
	PrettyPrint = "prettyPrint"
	Callback    = "callback"
	Fields      = "fields"
	Key         = "key"
)

// CommonBloggerParams are the query parameters shared by most Blogger v3 list
// endpoints.
const (
	MaxResults = "maxResults"
	PageToken  = "pageToken"
	FetchBodies = "fetchBodies"
	StartIndex  = "startIndex"
	Status      = "status"
	OrderBy     = "orderBy"
	SortOrder   = "sortOrder"
	Labels      = "labels"
	View        = "view"
	Alt         = "alt"
)

// MaxResultsRange bounds the per-page item count accepted by Blogger list
// endpoints.
type MaxResultsRange struct {
	Min int64
	Max int64
}

// BloggerListRange is the documented 1..100 window for maxResults.
var BloggerListRange = MaxResultsRange{Min: 1, Max: 100}

// Clamp constrains n to the range, returning the nearest bound.
func (r MaxResultsRange) Clamp(n int64) int64 {
	if n < r.Min {
		return r.Min
	}
	if n > r.Max {
		return r.Max
	}
	return n
}

// Contains reports whether n falls inside the range.
func (r MaxResultsRange) Contains(n int64) bool {
	return n >= r.Min && n <= r.Max
}

// CommonFilter describes the optional narrowing parameters that Blogger list
// endpoints accept.
type CommonFilter struct {
	Labels    []string
	Status    string
	OrderBy   string
	SortOrder string
	FetchBodies *bool
}

// Apply writes the non-empty filter fields onto the builder as query
// parameters. Empty values are skipped so unset filters never reach the wire.
func (f CommonFilter) Apply(b *Builder) *Builder {
	if b == nil {
		return b
	}

	if len(f.Labels) > 0 {
		b.Param(Labels, joinList(f.Labels))
	}
	if f.Status != "" {
		b.Param(Status, f.Status)
	}
	if f.OrderBy != "" {
		b.Param(OrderBy, f.OrderBy)
	}
	if f.SortOrder != "" {
		b.Param(SortOrder, f.SortOrder)
	}
	if f.FetchBodies != nil {
		b.Param(FetchBodies, boolParam(*f.FetchBodies))
	}

	return b
}

// Pagination describes the page window requested from a list endpoint.
type Pagination struct {
	MaxResults int64
	PageToken  string
}

// Apply writes the pagination window onto the builder.
func (p Pagination) Apply(b *Builder) *Builder {
	if b == nil {
		return b
	}

	if p.MaxResults > 0 {
		b.Param(MaxResults, itoa(BloggerListRange.Clamp(p.MaxResults)))
	}
	if p.PageToken != "" {
		b.Param(PageToken, p.PageToken)
	}

	return b
}

package builder

import (
	"bytes"
	"encoding/json"
	"fmt"
	"net/url"
	"strconv"
	"strings"
)

// PageToken is the opaque cursor Blogger returns as nextPageToken and accepts
// as the pageToken query parameter.
type PageToken string

// String returns the token as a plain string.
func (p PageToken) String() string {
	return string(p)
}

// IsZero reports whether the token is empty, meaning there is no next page.
func (p PageToken) IsZero() bool {
	return p == ""
}

// Query returns the token encoded for use in a URL query string.
func (p PageToken) Query() string {
	return url.QueryEscape(string(p))
}

// PaginationResult is the page envelope every Blogger list response is decoded
// into. Items stays raw so callers can decode it into their concrete model.
type PaginationResult struct {
	Items         []byte      `json:"items"`
	NextPageToken string      `json:"nextPageToken"`
	TotalItems    int64       `json:"totalItems"`
	ETag          string      `json:"etag"`
	Kind          string      `json:"kind"`
}

// NewPageToken validates a raw cursor and wraps it as a PageToken.
func NewPageToken(raw string) PageToken {
	return PageToken(strings.TrimSpace(raw))
}

// Next returns the cursor for the following page, or an empty token when the
// current page was the last one.
func (r PaginationResult) Next() PageToken {
	return NewPageToken(r.NextPageToken)
}

// HasMore reports whether another page can be requested.
func (r PaginationResult) HasMore() bool {
	return r.NextPageToken != ""
}

// Decode unmarshals the raw Items payload into v, returning an empty slice
// rather than nil when the page carried no items.
func (r PaginationResult) Decode(v interface{}) error {
	if v == nil {
		return fmt.Errorf("blogger: decode target is nil")
	}

	payload := bytes.TrimSpace(r.Items)
	if len(payload) == 0 {
		payload = []byte("[]")
	}

	return json.Unmarshal(payload, v)
}

// ParsePaginationResult decodes a raw list response body into a
// PaginationResult, tolerating a response that is itself a bare items array.
func ParsePaginationResult(payload []byte) (*PaginationResult, error) {
	result := &PaginationResult{Items: []byte("[]")}

	trimmed := bytes.TrimSpace(payload)
	if len(trimmed) == 0 {
		return result, nil
	}

	if trimmed[0] == '[' {
		result.Items = append([]byte{}, trimmed...)
		var items []json.RawMessage
		if err := json.Unmarshal(trimmed, &items); err != nil {
			return nil, err
		}
		result.TotalItems = int64(len(items))
		return result, nil
	}

	var envelope struct {
		Items         json.RawMessage `json:"items"`
		NextPageToken string          `json:"nextPageToken"`
		TotalItems    int64           `json:"totalItems"`
		ETag          string          `json:"etag"`
		Kind          string          `json:"kind"`
	}
	if err := json.Unmarshal(trimmed, &envelope); err != nil {
		return nil, err
	}

	if len(envelope.Items) > 0 {
		result.Items = append([]byte{}, envelope.Items...)
	}
	result.NextPageToken = envelope.NextPageToken
	result.TotalItems = envelope.TotalItems
	result.ETag = envelope.ETag
	result.Kind = envelope.Kind

	return result, nil
}

// PageTokenFromResponse extracts nextPageToken from a raw list response body.
func PageTokenFromResponse(payload []byte) (PageToken, error) {
	result, err := ParsePaginationResult(payload)
	if err != nil {
		return "", err
	}
	return result.Next(), nil
}

// Tokens walks a paginated endpoint by repeatedly calling fetch until the API
// stops returning a nextPageToken or maxPages pages have been collected.
func Tokens(maxPages int, fetch func(token PageToken) (*PaginationResult, error)) ([]*PaginationResult, error) {
	if fetch == nil {
		return nil, fmt.Errorf("blogger: fetch function is nil")
	}

	pages := []*PaginationResult{}
	token := PageToken("")

	for {
		page, err := fetch(token)
		if err != nil {
			return pages, err
		}
		if page == nil {
			return pages, nil
		}

		pages = append(pages, page)

		if !page.HasMore() {
			return pages, nil
		}
		if maxPages > 0 && len(pages) >= maxPages {
			return pages, nil
		}

		token = page.Next()
	}
}

func joinList(values []string) string {
	cleaned := []string{}
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			cleaned = append(cleaned, value)
		}
	}
	return strings.Join(cleaned, ",")
}

func boolParam(value bool) string {
	return strconv.FormatBool(value)
}

func itoa(value int64) string {
	return strconv.FormatInt(value, 10)
}

